function appealSum(s) {
  const n = s.length;
  const last = new Array(26).fill(-1);
  let total = 0;

  for (let i = 0; i < n; i++) {
    const letter = s.charCodeAt(i) - 97;
    const startChoices = i - last[letter];
    const endChoices = n - i;
    total += startChoices * endChoices;
    last[letter] = i;
  }
  return total;
}

