function appealSum(s) {
  let sum = 0;
  for (let start = 0; start < s.length; start++) {
    const seen = new Set();
    for (let end = start; end < s.length; end++) {
      seen.add(s[end]);
      sum += seen.size;
    }
  }
  return sum;
}

