function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = rand() < 0.2 ? 26 : 1 + Math.floor(rand() * 4);
  const n = size === 'small' ? 1 + Math.floor(rand() * 10) : 8000 + Math.floor(rand() * 2001);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * alphabet)];
  return [s];
}
